import{_ as o,l as r,o as e,c as l,v as i,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"LCP 与 Kasai","description":"","frontmatter":{"title":"LCP 与 Kasai","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lcp-kasai.md","filePath":"cs/lcp-kasai.md","lastUpdated":1789023840000}'),h={name:"cs/lcp-kasai.md"};function A(P,a,C,m,S,_){const s=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="lcp-与-kasai" tabindex="-1">LCP 与 Kasai <a class="header-anchor" href="#lcp-与-kasai" aria-label="Permalink to &quot;LCP 与 Kasai&quot;">​</a></h1><div class="epigraph"><p>$H[i]$ 是 $SA$ 上相邻两后缀的最长公共前缀；Kasai 用 $ISA$ 按文本顺序扫，摊还线性算出整张 $H$。</p><footer>—— 据 Kasai et al., Linear-Time Longest-Common-Prefix Computation in Suffix Arrays and Its Applications, CPM 2001；Manber and Myers 整理</footer></div><p><a href="/cs/suffix-array">上一课</a> 二分时可能对 \\(P\\) 反复比已经相等的前缀。RMQ 若建在 \\(LCP\\) 上，任意两后缀的 LCP 是 \\(SA\\) 区间最小值——接回<a href="/cs/sparse-table">稀疏表</a>。本课不重排后缀。缺口是定义 \\(LCP\\) 数组，以及 Kasai 线性算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(LCP[i]=\\mathrm{lcp}(T[SA[i-1]..], T[SA[i]..])\\)（下标约定课内固定一种）。已知 \\(SA\\) 与 \\(ISA\\)，Kasai：按 \\(k=ISA\\) 的文本位置 \\(i=0,1,\\ldots\\) 考虑后缀 \\(T[i..]\\) 与在 \\(SA\\) 中的前一名。若上一步 LCP 为 \\(h\\gt 0\\)，则这一步至少 \\(h-1\\)（去掉一个字符）。缺口是<strong>用这个 \\(h-1\\) 下界避免从零比</strong>，合计比较 \\(O(n)\\)。</p><p><span class="marginnote">Kasai et al., CPM 2001。有了 LCP，后缀数组 + RMQ 可模拟后缀树许多查询。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：<code>h=0</code>，对 <code>i in 0..n-1</code>，若 <code>ISA[i]&gt;0</code>，令 <code>j=SA[ISA[i]-1]</code>，从 <code>h</code> 起比较 \\(T[i+h]\\) 与 \\(T[j+h]\\)，写入 <code>LCP[ISA[i]]</code>，然后 <code>h=max(0,h-1)</code>。任意两后缀 \\(p,q\\) 的 lcp 等于 \\(LCP\\) 在 \\(SA\\) 上两者秩之间的最小值。</p>',8)),(e(),n(p,null,{default:t(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SA%5B%22SA%20%E4%B8%8E%20ISA%22%5D%20--%3E%20KASAI%5B%22%E6%8C%89%E6%96%87%E6%9C%AC%E5%BA%8F%E6%89%AB%2C%20h-1%20%E4%B8%8B%E7%95%8C%22%5D%0A%20%20KASAI%20--%3E%20LCP%5B%22LCP%20%E6%95%B0%E7%BB%84%22%5D%0A%20%20LCP%20--%3E%20RMQ%5B%22%E7%A8%80%E7%96%8F%E8%A1%A8%20RMQ%22%5D%0A%20%20RMQ%20--%3E%20PAIR%5B%22%E4%BB%BB%E6%84%8F%E4%B8%A4%E5%90%8E%E7%BC%80%20lcp%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>应用：本质不同子串个数 \\(n(n+1)/2-\\sum LCP\\)；重复串；与 KMP 前缀函数不同——这里对全体后缀。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正确性：文本位置 \\(i\\) 与 \\(i+1\\) 的后缀关系给出 \\(h\\) 的传递。不要在无哨兵时让比较越界。LCP 最小值用静态 RMQ，不需 Fenwick。</p><p>后缀树把这些 lcp 变成显式边，下一课收指针树；本课数组已够多数统计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写稀疏后缀数组。动态 LCP 维护复杂。后缀树与 SAM 仍有「所有出现位置」的显式 coprime 结构需求。</p><p>后课默认：静态 \\(SA\\) 必配 \\(LCP\\)。要显式后缀链与边，用后缀树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(LCP[i]\\)：SA 相邻后缀公共前缀长。</li><li>Kasai：\\(O(n)\\) 借助 \\(h-1\\)。</li><li>任意对 lcp = 区间最小 LCP。</li><li>出处：Kasai et al., CPM 2001；Manber and Myers。</li></ul>',9))])}const u=o(h,[["render",A]]);export{f as __pageData,u as default};
